    return best;
  }

  private startEating(b: Blob, tr: Tree) {
    const lim = Math.round(this.p.fruitLimit);
    for (let i = 0; i < lim; i++) {
      const s = tr.slots[i];
      if (s.g >= 1 && !s.reserved) {
        s.reserved = true;
