        b.targetTree = tr.id;
        b.action = 'eating';
        b.timer = b.timerTotal = Math.max(0.05, this.p.blueEat);
        b.vx *= 0.3;
        b.vy *= 0.3;
        this.events.push({ type: 'pickup', kind: 'blue', x: tr.x + s.ox, y: tr.y, t: this.t });
        return;
