    }
  }

  private finishEating(b: Blob) {
    const tr = this.trees[b.targetTree];
    const s = tr?.slots[b.eatSlot];
    if (s) {
      s.reserved = false;
      s.g = 0;
      s.delay = this.p.fruitDelay;
