          b.action = 'catching breath';
          b.ignoreBlob = q.id;
          b.targetBlob = -1;
          b.timer = b.timerTotal = 1.5;
        } else {
          b.action = 'hunting';
          const lead = Math.min(1, d / speed) * 0.5;
          dx = q.x + q.vx * lead - b.x;
          dy = q.y + q.vy * lead - b.y;
