        dy = Math.sin(b.wander) + e.y;
        want = 0.55;
      }
      if (b.timer === 0) {
        let sx = 0, sy = 0;
        this.redGrid.forEachNear(b.x, b.y, 1.8, (o, d2) => {
          if (o === b || d2 < 1e-6) return;
          const d = Math.sqrt(d2);
          const w = (1.8 - d) / 1.8;
