rm scripts/batch.ts scripts/trace.ts; cat > scripts/presets.ts <<'EOF'
import { Simulation } from '../src/sim.ts';
import { presetParams } from '../src/params.ts';
const args = (globalThis as any).process.argv.slice(2);
const preset = args[0];
const over = JSON.parse(args[1] ?? '{}');
const secs = Number(args[2] ?? 900);
for (let seed = 1; seed <= Number(args[3] ?? 4); seed++) {
  const sim = new Simulation({ ...presetParams(preset, seed), ...over });
  while (sim.t < secs) sim.step();
  const pts = sim.history.filter((_, i) => i % 60 === 0).map((s) => `${s.blue}/${s.red}`);
  const bmax = Math.max(...sim.history.map((h) => h.blue));
  const rmax = Math.max(...sim.history.map((h) => h.red));
  console.log(`${preset} s${seed} bmax=${bmax} rmax=${rmax} | ${pts.join(' ')}`);
}
EOF
which portly; portly --help 2>&1 | head -30

