+  ctx.strokeStyle = CHART_COLORS.grid;
+  ctx.lineWidth = 1;
+  for (let k = 0; k <= 4; k++) {
+    const y = T + (ph * k) / 4;
+    ctx.beginPath();
+    ctx.moveTo(L, y);
+    ctx.lineTo(L + pw, y);
