    grid-column: 1;
    grid-row: 1;
  }
  .charts {
    grid-column: 1;
    grid-row: 2;
  }
  .controls {
    grid-column: 2;
    grid-row: 1 / span 2;
    max-height: none;
    position: static;
  }
  .chart-row {
    grid-template-columns: 1fr 1fr 1.3fr;
  }
  .summary-card {
    grid-column: auto;
  }
}

@media (max-width: 900px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .world-card,
  .charts,
  .controls {
    grid-column: 1;
    grid-row: auto;
  }
  .world-card {
    min-height: 420px;
  }
  .chart-row {
    grid-template-columns: 1fr;
  }
  .presets {
    margin-left: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .btn.pending {
    animation: none;
  }
}

