    const ce = Math.cos(this.elev);
    // vertical extent in world units: dish ellipse + pot wall below + tree tops poking above the back rim
    const extent = 2 * (R + 1) * se + 3.2 * ce + 5 * ce;
    const fitW = (this.w * 0.94) / (2 * (R + 1));
