cat > /tmp/g7.js <<'EOF'
const page = await browser.getPage("g");
await page.reload({ waitUntil: "domcontentloaded", timeout: 10000 });
await page.waitForTimeout(12000);
const rect = await page.evaluate(() => { const r = document.getElementById('world').getBoundingClientRect(); return { x: r.left, y: r.top }; });
const target = await page.evaluate(() => { const g = window.garden; const s = g.sim(); const b = s.blobs.find((b) => b.kind === 'blue' && (b.action === 'eating' || b.action === 'seeking fruit')) || s.blobs[0]; const p = g.renderer.screenPos.get(b.id); return { id: b.id, x: p.x, y: p.y }; });
await page.mouse.click(rect.x + target.x, rect.y + target.y);
await page.waitForTimeout(300);
const insp = await page.evaluate(() => { const el = document.getElementById('inspector'); return { hidden: el.hidden, text: el.innerText, sel: window.garden.renderer.selected }; });
const cdp = await page.context().newCDPSession(page);
const full = await cdp.send("Page.captureScreenshot", { format: "png" });
await writeFile("g-full.txt", full.data);
const crop = await cdp.send("Page.captureScreenshot", { format: "png", clip: { x: rect.x + target.x - 170, y: rect.y + target.y - 110, width: 340, height: 220, scale: 2.5 } });
await writeFile("g-crop.txt", crop.data);
console.log(JSON.stringify({ target, insp }));
EOF
