:root {
  --bg: #fbf3e4;
  --bg2: #f4e6cf;
  --card: #fffaf1;
  --ink: #3a2d22;
  --ink2: #7a6655;
  --line: rgba(90, 70, 50, 0.14);
  --fruit: #5fae2e;
  --blue: #2f86e6;
  --red: #e2493f;
  --accent: #f0a04b;
  --radius: 18px;
  --shadow: 0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 8px 24px -12px rgba(90, 60, 30, 0.35);
  font-family: ui-rounded, 'SF Pro Rounded', 'Nunito', system-ui, -apple-system, sans-serif;
  color: var(--ink);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  background:
    radial-gradient(1200px 600px at 20% -10%, #fff6dc 0%, transparent 60%),
    radial-gradient(900px 500px at 110% 10%, #f8dcc4 0%, transparent 60%),
    var(--bg);
}

button,
input {
  font: inherit;
  color: inherit;
}

.app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  padding: 14px 16px 18px;
  gap: 12px;
}

.topbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px 18px;
}

.topbar h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.transport {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.btn {
  border: 1px solid var(--line);
  background: var(--card);
  border-radius: 999px;
  padding: 7px 14px;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
  box-shadow: var(--shadow);
  transition: transform 0.12s, background 0.15s;
  white-space: nowrap;
}

.btn:hover {
  transform: translateY(-1px);
  background: #fff;
}

.btn:active {
  transform: translateY(1px) scale(0.98);
}

.btn:focus-visible,
.preset:focus-visible,
.mini:focus-visible,
input[type='range']:focus-visible {
  outline: 3px solid rgba(240, 160, 75, 0.55);
  outline-offset: 2px;
}

.btn.primary {
  background: linear-gradient(180deg, #ffb865, #f08e3a);
  color: #fff;
  border-color: #d97a2b;
  min-width: 92px;
}

.btn.primary.playing {
  background: linear-gradient(180deg, #8fd36b, #58a73a);
  border-color: #4b8f31;
}

.btn.pending {
  background: #fff3d1;
  border-color: #f0a04b;
  animation: nudge 1.6s ease-in-out infinite;
}

@keyframes nudge {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(240, 160, 75, 0.5);
  }
  50% {
    box-shadow: 0 0 0 6px rgba(240, 160, 75, 0);
  }
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 12px;
  border-radius: 999px;
  background: var(--card);
  border: 1px solid var(--line);
  font-size: 12px;
  font-weight: 700;
  color: var(--ink2);
}

.speed input {
  width: 90px;
}

.speed output {
  min-width: 30px;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.presets {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-left: auto;
}

.preset {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.55);
  border-radius: 12px;
  padding: 6px 10px;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, transform 0.12s;
}

.preset:hover {
  background: #fff;
  transform: translateY(-1px);
}

.preset[aria-checked='true'] {
  background: var(--ink);
  color: #fff8ec;
  border-color: var(--ink);
}

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr) 320px;
  grid-template-rows: auto;
  gap: 12px;
  flex: 1;
  min-height: 0;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.world-card {
  position: relative;
  min-height: 560px;
  overflow: hidden;
  background:
    radial-gradient(80% 70% at 50% 40%, #fff9ec 0%, #f6e3c6 100%);
}

#world {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  cursor: grab;
  touch-action: none;
}

#world.dragging {
  cursor: grabbing;
}

#world.hovering {
  cursor: pointer;
}

.hud {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 12px;
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  z-index: 2;
  pointer-events: none;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 11px;
  border-radius: 999px;
  background: rgba(255, 252, 245, 0.88);
  border: 1px solid var(--line);
  font-size: 12.5px;
  font-weight: 600;
  color: var(--ink2);
  backdrop-filter: blur(6px);
}

.chip b {
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  font-size: 14px;
}

.chip i {
  width: 10px;
  height: 12px;
  border-radius: 50%;
}

.chip.fruit i {
  background: var(--fruit);
  width: 10px;
  height: 10px;
}

.chip.blue i {
  background: var(--blue);
}

.chip.red i {
  background: var(--red);
}

.chip.time {
  margin-left: auto;
}

.world-hint {
  position: absolute;
  bottom: 10px;
  right: 12px;
  font-size: 11px;
  color: var(--ink2);
  opacity: 0.75;
  pointer-events: none;
}

.drop {
  position: absolute;
  top: 48px;
  left: 12px;
  display: flex;
  gap: 6px;
  z-index: 2;
}

.mini {
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 3px 10px;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  background: rgba(255, 252, 245, 0.85);
}

.mini.blue {
  color: var(--blue);
}

.mini.red {
  color: var(--red);
}

.mini:hover {
  background: #fff;
}

.inspector {
  position: absolute;
  left: 12px;
  bottom: 12px;
  width: 250px;
  z-index: 3;
  padding: 12px 14px;
  border-radius: 16px;
  background: rgba(255, 252, 245, 0.96);
  border: 1px solid var(--line);
  box-shadow: 0 12px 30px -12px rgba(60, 40, 20, 0.45);
  font-size: 12.5px;
  animation: pop 0.18s ease-out;
}

@keyframes pop {
  from {
    transform: translateY(6px) scale(0.98);
    opacity: 0;
  }
}

.inspector .ihead {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.inspector .avatar {
  width: 26px;
  height: 30px;
  border-radius: 50%;
  position: relative;
  flex: none;
}

.inspector .avatar.blue {
  background: radial-gradient(circle at 35% 30%, #9fd8ff, #3d9bf0 55%, #1d5fb8);
}

.inspector .avatar.red {
  background: radial-gradient(circle at 35% 30%, #ffb3a8, #f25a4e 55%, #b8262a);
}

.inspector .avatar::before,
.inspector .avatar::after {
  content: '';
  position: absolute;
  top: 12px;
  width: 4px;
  height: 5px;
  border-radius: 50%;
  background: #1b1b2b;
}

.inspector .avatar::before {
  left: 8px;
}

.inspector .avatar::after {
  right: 8px;
}

.inspector h3 {
  margin: 0;
  font-size: 15px;
  line-height: 1.1;
}

.inspector .kind {
  font-size: 11px;
  color: var(--ink2);
  font-weight: 600;
}

.inspector .close {
  margin-left: auto;
  border: none;
  background: transparent;
  font-size: 16px;
  cursor: pointer;
  color: var(--ink2);
  padding: 2px 6px;
  border-radius: 8px;
}

.inspector .close:hover {
  background: var(--bg2);
}

.inspector .action {
  display: inline-block;
  padding: 3px 9px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 12px;
  background: var(--bg2);
  margin-bottom: 8px;
}

.bar {
  height: 8px;
  border-radius: 999px;
  background: #efe3cf;
  overflow: hidden;
  margin: 3px 0 8px;
}

.bar > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  transition: width 0.2s;
}

.bar.energy > span {
  background: linear-gradient(90deg, #f7c948, #8fd36b);
}

.bar.timer > span {
  background: linear-gradient(90deg, #c6a3ff, #8a6ae6);
}

.inspector dl {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 3px 10px;
  margin: 0;
}

.inspector dt {
  color: var(--ink2);
}

.inspector dd {
  margin: 0;
  text-align: right;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.inspector .row {
  display: flex;
  justify-content: space-between;
  font-weight: 600;
  color: var(--ink2);
}

.inspector .row b {
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.inspector .gone {
  margin: 4px 0 8px;
  padding: 6px 8px;
  border-radius: 10px;
  background: #f3e9f7;
  color: #6a4a82;
  font-weight: 600;
}

.charts {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
}

.card-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 14px 0;
  flex-wrap: wrap;
}

.card-head h2 {
  margin: 0;
  font-size: 13.5px;
  font-weight: 800;
}

.card-head .sub {
  font-size: 11px;
  color: var(--ink2);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.sw {
  display: inline-block;
  width: 16px;
  height: 0;
  border-top: 2px solid var(--ink2);
  margin-left: 4px;
}

.sw.dash {
  border-top-style: dashed;
}

.legend {
  display: flex;
  gap: 10px;
  font-size: 11.5px;
  font-weight: 700;
}

.lg::before {
  content: '';
  display: inline-block;
  width: 14px;
  height: 3px;
  border-radius: 2px;
  margin-right: 5px;
  vertical-align: middle;
  background: currentColor;
}

.lg small {
  font-weight: 500;
  opacity: 0.75;
}

.lg.fruit {
  color: var(--fruit);
}

.lg.blue {
  color: var(--blue);
}

.lg.red {
  color: var(--red);
}

.chart-main canvas {
  width: 100%;
  height: 230px;
  display: block;
}

.chart-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.chart-row canvas {
  width: 100%;
  height: 170px;
  display: block;
}

.summary-card {
  grid-column: 1 / -1;
}

.summary {
  list-style: none;
  margin: 8px 0 0;
  padding: 0 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.summary li {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  font-size: 13px;
  line-height: 1.35;
  padding: 7px 10px;
  border-radius: 12px;
  background: #fbf4e6;
}

.summary li.good {
  background: #eef8e5;
}

.summary li.warn {
  background: #fdf0e3;
}

.summary li .i {
  flex: none;
}

.totals {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  margin: 10px 14px 14px;
}

.totals div {
  background: var(--bg);
  border-radius: 10px;
  padding: 6px 8px;
}

.totals dt {
  font-size: 10.5px;
  color: var(--ink2);
  font-weight: 600;
}

.totals dd {
  margin: 0;
  font-weight: 800;
  font-size: 15px;
  font-variant-numeric: tabular-nums;
}

.controls {
  padding: 6px 0 10px;
  overflow-y: auto;
  max-height: calc(100vh - 90px);
  position: sticky;
  top: 12px;
  align-self: start;
}

.group {
  padding: 8px 14px 4px;
