:root {
  --bg: #fbf3e4;
  --bg2: #f4e6cf;
  --card: #fffaf1;
  --ink: #3a2d22;
  --ink2: #7a6655;
  --line: rgba(90, 70, 50, 0.14);
  --fruit: #5fae2e;
  --blue: #2f86e6;
  --red: #e2493f;
  --accent: #f0a04b;
  --radius: 18px;
  --shadow: 0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 8px 24px -12px rgba(90, 60, 30, 0.35);
  font-family: ui-rounded, 'SF Pro Rounded', 'Nunito', system-ui, -apple-system, sans-serif;
  color: var(--ink);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  background:
    radial-gradient(1200px 600px at 20% -10%, #fff6dc 0%, transparent 60%),
    radial-gradient(900px 500px at 110% 10%, #f8dcc4 0%, transparent 60%),
    var(--bg);
}

button,
input {
  font: inherit;
  color: inherit;
}

.app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  padding: 14px 16px 18px;
  gap: 12px;
}

.topbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px 18px;
}

.topbar h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.transport {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.btn {
  border: 1px solid var(--line);
  background: var(--card);
  border-radius: 999px;
  padding: 7px 14px;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
  box-shadow: var(--shadow);
  transition: transform 0.12s, background 0.15s;
  white-space: nowrap;
}

.btn:hover {
  transform: translateY(-1px);
  background: #fff;
}

.btn:active {
  transform: translateY(1px) scale(0.98);
}

.btn:focus-visible,
.preset:focus-visible,
.mini:focus-visible,
input[type='range']:focus-visible {
  outline: 3px solid rgba(240, 160, 75, 0.55);
  outline-offset: 2px;
}

.btn.primary {
  background: linear-gradient(180deg, #ffb865, #f08e3a);
  color: #fff;
  border-color: #d97a2b;
  min-width: 92px;
}

.btn.primary.playing {
  background: linear-gradient(180deg, #8fd36b, #58a73a);
  border-color: #4b8f31;
}

.btn.pending {
  background: #fff3d1;
  border-color: #f0a04b;
  animation: nudge 1.6s ease-in-out infinite;
}

@keyframes nudge {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(240, 160, 75, 0.5);
  }
  50% {
    box-shadow: 0 0 0 6px rgba(240, 160, 75, 0);
  }
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 12px;
  border-radius: 999px;
  background: var(--card);
  border: 1px solid var(--line);
  font-size: 12px;
  font-weight: 700;
  color: var(--ink2);
}

.speed input {
  width: 90px;
}

.speed output {
  min-width: 30px;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.presets {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
